describe('LangBlock - 다중언어 블록 테스트', () => {
  it('LB-1: @lang("rust") 파싱 → LangBlock AST sourceCode 추출', () => {
    const code = `
@lang("rust")
---
#[no_mangle]
pub extern "C" fn test_fn() {}
---
`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();

    expect(ast.body.length).toBeGreaterThan(0);
    const langBlock = ast.body[0] as any;
    expect(langBlock.type).toBe('LangBlock');
    expect(langBlock.lang).toBe('rust');
    expect(langBlock.sourceCode).toContain('#[no_mangle]');
  });

  it('LB-2: @artifact, @compile 파싱', () => {
    const code = `
@lang("rust")
@artifact("librustcore.so")
