---
`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();

    const langBlock = ast.body[0] as any;
    expect(langBlock.artifact).toBe('librustcore.so');
    expect(langBlock.compileCmd).toContain('rustc');
  });

  it('LB-3: Rust extern 함수 시그니처 추출', () => {
    const code = `
@lang("rust")
@artifact("lib.so")
@compile("rustc -o lib.so")
---
#[no_mangle]
pub extern "C" fn rust_fib(n: i32) -> i64 { 0 }
---
`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);

    expect(result.c).toContain('extern long long rust_fib(int n);');
  });

